inline bool calibrated(world_weapon_loadout::Weapon w){return w==world_weapon_loadout::Weapon::GreatAxe||w==world_weapon_loadout::Weapon::Staff;}
inline Polygon polygon(world_weapon_loadout::Weapon w,unsigned direction){
 if(direction>4||!calibrated(w))return {nullptr,0};
 const bool axe=w==world_weapon_loadout::Weapon::GreatAxe;
 switch(direction){
 case 0:return axe?Polygon{great_axe_left,sizeof(great_axe_left)/sizeof(Point)}:Polygon{staff_left,sizeof(staff_left)/sizeof(Point)};
 case 1:return axe?Polygon{great_axe_right,sizeof(great_axe_right)/sizeof(Point)}:Polygon{staff_right,sizeof(staff_right)/sizeof(Point)};
 case 2:return axe?Polygon{great_axe_high,sizeof(great_axe_high)/sizeof(Point)}:Polygon{staff_high,sizeof(staff_high)/sizeof(Point)};
 case 3:return axe?Polygon{great_axe_low,sizeof(great_axe_low)/sizeof(Point)}:Polygon{staff_low,sizeof(staff_low)/sizeof(Point)};
 case 4:return axe?Polygon{great_axe_thrust,sizeof(great_axe_thrust)/sizeof(Point)}:Polygon{staff_thrust,sizeof(staff_thrust)/sizeof(Point)};
 }return {nullptr,0};
}
inline double separation(Polygon poly,double x,double z){
 if(!poly.points||poly.count<3||!std::isfinite(x)||!std::isfinite(z)||std::abs(x)>8||std::abs(z)>8)return std::numeric_limits<double>::infinity();
 bool inside=true;double nearest=std::numeric_limits<double>::infinity();
 for(std::size_t i=0;i<poly.count;++i){
  const Point a=poly.points[i],b=poly.points[(i+1)%poly.count];const double dx=b.x-a.x,dz=b.z-a.z;
  if(dx*(z-a.z)-dz*(x-a.x)<-1e-10)inside=false;
  const double length=dx*dx+dz*dz;const double t=length>1e-20?std::clamp(((x-a.x)*dx+(z-a.z)*dz)/length,0.,1.):0.;
  nearest=std::min(nearest,std::hypot(x-a.x-t*dx,z-a.z-t*dz));
 }return inside?0.:nearest;
}
inline bool intersects(world_weapon_loadout::Weapon weapon,unsigned direction,double x,double z,bool weapon_guard=false){
 if(z<0||!std::isfinite(z))return false;
 return separation(polygon(weapon,direction),x,z)<=(weapon_guard?guard_radius:body_radius)+1e-9;
}
